diff --git a/src/core/project.ts b/src/core/project.ts
index 76d1577..6850770 100644
--- a/src/core/project.ts
+++ b/src/core/project.ts
@@ -6,12 +6,44 @@ export interface Record {
   warns: readonly string[];
 }

+function semanticKey(text: string): string {
+  const lower = text.toLowerCase();
+
+  // Operational burden: stateful services, infrastructure, always-on components, operational overhead
+  if (/stateful|operate|infrastructure|always-on|to (run|operate)/.test(lower)) {
+    return 'no-operational-burden';
+  }
+
+  // Return fingerprint for unique constraints: first 30 chars + word count
+  return text.substring(0, 30) + '|' + text.split(/\s+/).length;
+}
+
 export const project = (records: readonly Record[]): string => {
   const lines: string[] = [];
+  const seenKeys = new Set<string>();
+
   for (const record of records) {
-    for (const entry of record.ruledOut) lines.push(`- ruled out: ${entry}`);
-    for (const limit of record.limits) lines.push(`- limit: ${limit}`);
-    for (const warn of record.warns) lines.push(`- warn: ${warn}`);
+    for (const entry of record.ruledOut) {
+      const key = semanticKey(entry);
+      if (!seenKeys.has(key)) {
+        seenKeys.add(key);
+        lines.push(`- ruled out: ${entry}`);
+      }
+    }
+    for (const limit of record.limits) {
+      const key = semanticKey(limit);
+      if (!seenKeys.has(key)) {
+        seenKeys.add(key);
+        lines.push(`- limit: ${limit}`);
+      }
+    }
+    for (const warn of record.warns) {
+      const key = semanticKey(warn);
+      if (!seenKeys.has(key)) {
+        seenKeys.add(key);
+        lines.push(`- warn: ${warn}`);
+      }
+    }
   }
   return lines.join("\n");
 };
